"""Regenerate C/MQL declarations from exported definitions; check_api.py verifies them."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
source = (ROOT / 'kernel.cu').read_text(encoding='utf-8')
functions = re.findall(r'DLL_EXPORT\s+(\w+)\s+DLL_CALL\s+(DN_\w+)\(([^{}]*?)\)\s*try\s*\{', source)
header_path = ROOT / 'include/MQL5GPULibrary.h'
header = header_path.read_text(encoding='utf-8').split('DN_API int DN_CALL')[0]
mql = '''#ifndef MQL5_GPU_LIBRARY_LSTM_MQH
#define MQL5_GPU_LIBRARY_LSTM_MQH
// Generated by tools/generate_api.py. Contracts: docs/API.md and docs/MANUAL.cs.md.
// Graph types: 0 LSTM, 1 GRU, 2 RNN, 3 Dense, 4 Identity.
// Merge: 0 concatenate, 1 sum. Dense activation: 0 linear, 1 tanh, 2 ReLU, 3 sigmoid.
// Parents: -1 external input, otherwise an earlier zero-based node ID.
#import "MQL5GPULibrary_LSTM.dll"
'''
for result, name, arguments in functions:
    result = result.replace('MQL_BOOL', 'int')
    arguments = ' '.join(arguments.split())
    header += f'DN_API {result} DN_CALL {name}({arguments or "void"});\n'
    arguments = re.sub(r'(const )?(double|int|char|short)\*\s*(\w+)',
        lambda m: f'{m[1] or ""}{m[2]} &{m[3]}' + ('[]' if m[3] in ('X','T','Y','buf','parents') else ''), arguments)
    mql += f'{result} {name}({arguments});\n'
header += '\n#ifdef __cplusplus\n}\n#endif\n'
mql += '#import\n#endif\n'
header_path.write_text(header, encoding='utf-8')
(ROOT / 'MQL5/Include/MQL5GPULibrary.mqh').write_text(mql, encoding='utf-8')
